#!/usr/bin/env -S uv run --script
# Synced from bootstrap: repo/tools/git/tasks/git-worktree-delete.py. Do not edit this file.
# The next sync writes it again, and each change in this file is lost.
# /// script
# requires-python = ">=3.14"
# dependencies = []
# ///
# MISE description="Delete the worktree of a branch, and the branch when a core branch has it"
# MISE tools={uv="latest", python="3.14"}
# USAGE arg "<branch>" help="the branch whose worktree to delete"

# The task finds the worktree by its branch in `git worktree list`, at any
# path. git refuses to remove a worktree with changes. The branch goes only
# when a core branch (core_branches of `.config/bootstrap/repo.toml`) has each
# of its commits: `git branch -d` compares with the HEAD of this checkout,
# which can be any branch.

import os
import subprocess
import sys

sys.dont_write_bytecode = True
sys.path.insert(0, f"{os.environ['MISE_PROJECT_ROOT']}/.config/mise/tasks/_scripts")
import helpers  # noqa: E402

# mise sets `usage_branch` from the `# USAGE arg` above.
BRANCH = os.environ.get("usage_branch", "")

helpers.print_header(f"Deleting the worktree of {BRANCH} ...")

CORE = helpers.bootstrap_get("repo.core_branches")
core_value = CORE.get("value") if isinstance(CORE, dict) else None
if core_value is None or core_value is False:
  core_value = []
if not isinstance(core_value, list):
  helpers.print_error("cannot read core_branches of .config/bootstrap/repo.toml.")
  sys.exit(1)
CORE_LIST = [str(core) for core in core_value]
if BRANCH in CORE_LIST:
  helpers.print_error(f"'{BRANCH}' is a core branch, and this task never deletes a core branch.")
  sys.exit(2)

listing = subprocess.run(["git", "worktree", "list", "--porcelain"], check=False, stdout=subprocess.PIPE, text=True)
if listing.returncode != 0:
  sys.exit(listing.returncode)
WORKTREE = ""
path = ""
for line in listing.stdout.split("\n"):
  if line.startswith("worktree "):
    path = line.removeprefix("worktree ")
  elif line.startswith("branch ") and line.removeprefix("branch ") == f"refs/heads/{BRANCH}":
    WORKTREE = path
    break
if not WORKTREE:
  helpers.print_error(f"no worktree has the branch '{BRANCH}'.")
  sys.exit(1)

# The folder of the run, with each symlink resolved, against the folder of the
# worktree.
start = os.environ.get("MISE_ORIGINAL_CWD") or os.environ.get("PWD") or os.getcwd()
toplevel = subprocess.run(
  ["git", "-C", start, "rev-parse", "--show-toplevel"],
  check=False,
  stdout=subprocess.PIPE,
  stderr=subprocess.DEVNULL,
  text=True,
)
HERE = toplevel.stdout.rstrip("\n") if toplevel.returncode == 0 else ""
HERE = HERE or "/"
HERE = os.path.realpath(HERE) if os.path.isdir(HERE) else ""
THERE = os.path.realpath(WORKTREE) if os.path.isdir(WORKTREE) else WORKTREE
if HERE == THERE:
  helpers.print_error(f"this run is inside {WORKTREE}, the worktree it would remove.")
  helpers.print_warn("- run it from another worktree")
  sys.exit(2)

helpers.print_info(f"Removing {WORKTREE}")
if subprocess.run(["git", "worktree", "remove", WORKTREE], check=False).returncode != 0:
  helpers.print_error("git worktree remove failed.")
  sys.exit(1)
helpers.print_success(f"Removed {WORKTREE}")


def ref_exists(ref):
  """Whether git has the ref."""
  return subprocess.run(["git", "show-ref", "--verify", "--quiet", ref], check=False).returncode == 0


# The local ref of each core branch, else its ref on origin. The loop skips a
# core branch with neither.
MERGED_INTO = ""
for core in CORE_LIST:
  if not core:
    continue
  if ref_exists(f"refs/heads/{core}"):
    REF = f"refs/heads/{core}"
  elif ref_exists(f"refs/remotes/origin/{core}"):
    REF = f"refs/remotes/origin/{core}"
  else:
    continue
  ancestor = subprocess.run(["git", "merge-base", "--is-ancestor", f"refs/heads/{BRANCH}", REF], check=False)
  if ancestor.returncode == 0:
    MERGED_INTO = REF.removeprefix("refs/heads/").removeprefix("refs/remotes/")
    break

if not MERGED_INTO:
  helpers.print_error(f"no core branch has each commit of '{BRANCH}', so the branch stays.")
  helpers.print_warn(f"- delete it anyway: `git branch -D {BRANCH}`")
  sys.exit(1)

# -D is safe here: the test above proved that MERGED_INTO has the branch.
if subprocess.run(["git", "branch", "-D", BRANCH], check=False, stdout=subprocess.DEVNULL).returncode != 0:
  helpers.print_error(f"git branch -D {BRANCH} failed.")
  sys.exit(1)
helpers.print_success(f"Deleted the branch {BRANCH}, merged into {MERGED_INTO}")
